out=Path('/workspace/crate-review/bones');mode=os.environ.get('ROLLING_BONES_MODE','full');r={'mode':mode,'errors':[],'captureMethod':'captureBonusReviewFrame normal gameplay renderer at native resolution'}
pilot='''({kind,name,index})=>{const g=window.__game,p=g.player,l=g.getLevel(),s=window.__bonesSource,native=p.step.bind(p),prefix=name,boxes=l.crates.filter(b=>s.components[b.mesh.userData.editorIdx]?.nm?.startsWith(prefix)),cp=l.checkpoints[index],gate=l.finishBox.getCenter(p.pos.clone());let frames=0,lastSpin=false;window.mainRun={done:false};p.step=(dt,input,level)=>{const q=kind==='harvest'?boxes.filter(b=>b.alive).sort((a,b)=>a.box.min.y-b.box.min.y)[0]?.mesh.position:kind==='checkpoint'?cp.spawnPos:gate;const target=q??p.pos,dx=target.x-p.pos.x,dz=target.z-p.pos.z,d=Math.hypot(dx,dz)||1,f=(p.courseInputDirection(l)??p.camDir),n=Math.hypot(f.x,f.z)||1,spin=p.spinning||!lastSpin;lastSpin=spin;const pace=d>3?1:p.spinning?.3:0;input.moveX=(dx*-f.z+dz*f.x)/d/n*pace;input.moveY=(dx*f.x+dz*f.z)/d/n*pace;input.spinHeld=spin;input.spinPressed=spin&&!p.spinning;input.jumpHeld=input.jumpPressed=input.jumpReleased=input.grindHeld=input.grindPressed=false;native(dt,input,level);frames++;window.mainRun={done:false,frames,position:p.pos.toArray(),spinning:p.spinning,skating:p.freeSkate,remaining:boxes.filter(b=>b.alive).length,sameLevel:g.getLevel()===l,blocked:g.gameFlow.blocksGameplay};if(kind==='harvest'&&boxes.every(b=>!b.alive)||kind==='checkpoint'&&cp.active||p.state==='finished'||p.state==='dead'||frames>1800){window.mainRun={done:true,frames,state:p.state,crates:p.cratesBroken,lives:p.lives,position:p.pos.toArray(),collected:boxes.filter(b=>!b.alive).length,checkpoint:cp?.active};p.step=native;input.moveX=input.moveY=0;input.spinHeld=input.spinPressed=false;}};}'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader','--remote-debugging-port=9224'])
 page=b.new_page(viewport={'width':240 if mode=='lite' else 480,'height':135 if mode=='lite' else 270},service_workers='block');page.set_default_timeout(900000)
