  record('inventory',page.evaluate('(()=>{const l=window.__game.getLevel();return{physical:l.crates.length,total:l.totalCrates,bonus:l.bonusCrateTotal,checkpoints:l.checkpoints.length,enemies:l.enemies.length}})()'));assert r['inventory']=={'physical':118,'total':105,'bonus':22,'checkpoints':6,'enemies':0}
