   lives=page.evaluate('window.__game.player.lives');page.evaluate('()=>{const g=window.__game,p=g.player;p.pos.y=g.getLevel().killY-5;p.grounded=false;p.snapRenderInterpolation()}');page.wait_for_function('n=>{const g=window.__game,p=g.player;return p.lives===n-1&&p.grounded&&p.state!=="dead"&&p.pos.distanceTo(g.getLevel().currentSpawn)<.4}',arg=lives)
   record('recovery',page.evaluate('(()=>{const g=window.__game,l=g.getLevel(),s=window.__bonesSource;return{lives:g.player.lives,credit:g.player.cratesBroken,bankedGone:l.crates.filter(b=>s.components[b.mesh.userData.editorIdx]?.nm?.startsWith("Bones shelter / section 1 / cache 1 /")&&!b.alive).length,restored:l.crates.filter(b=>s.components[b.mesh.userData.editorIdx]?.nm?.startsWith("Bones shelter / section 1 / cache 2 /")&&b.alive).length,position:g.player.pos.toArray()}})()'));assert r['recovery']['restored']==5 and r['recovery']['bankedGone']==4
