   page.evaluate('()=>{const g=window.__game,p=g.player;p.pos.y=g.getLevel().killY-5;p.grounded=false;p.snapRenderInterpolation()}');ready('rolling-bones')
   record('bonusFailure',page.evaluate('(()=>{const g=window.__game;return{lives:g.player.lives,banked:g.player.bonusCrates,completed:g.getLevel().bonusRoundCompleted,sameParent:g.getLevel()===window.__parent}})()'));assert r['bonusFailure']=={'lives':before,'banked':0,'completed':False,'sameParent':True}
   page.evaluate('window.__game.enterBonusRound()');ready('bonus:rolling-bones');page.wait_for_function('window.__game.player.grounded');record('bonusRetry',page.evaluate('(()=>{const l=window.__game.getLevel();return{physical:l.crates.length,alive:l.crates.every(c=>c.alive)}})()'));assert r['bonusRetry']=={'physical':22,'alive':True}
   page.evaluate("async()=>{const m=await import('/tools/moonbone-browser-runtime.mjs');m.installMoonbonePilot()}");page.wait_for_function('window.moonbonePilotReport.done');record('bonusJourney',page.evaluate('window.moonbonePilotReport'));assert not r['bonusJourney']['failure'] and r['bonusJourney']['result']['cratesBroken']==22 and r['bonusJourney']['result']['deaths']==0
   ready('rolling-bones');record('bonusBanked',page.evaluate('({count:window.__game.player.bonusCrates,completed:window.__game.getLevel().bonusRoundCompleted,sameParent:window.__game.getLevel()===window.__parent})'));assert r['bonusBanked']=={'count':22,'completed':True,'sameParent':True}
